package com.wiseway.service;
import com.wiseway.api.ApiDtos.CompareRequest; import com.wiseway.domain.PreferenceProfile; import java.util.*; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*;
class RecommendationServiceCompareTest { @Test void resolvedCoordinatesProduceRoadOptions(){RoutingProvider provider=(a,b)->Optional.of(new RoutingProvider.Route(12000,1800,"{\"type\":\"LineString\",\"coordinates\":[]}","OSRM"));var service=new RecommendationService(new LocationService(),provider,new FareCalculationService());var r=service.compare(new CompareRequest("Rohtak", "Gurugram",28.8955,76.6066,28.4595,77.0266,null,PreferenceProfile.BALANCED,null),Set.of());assertFalse(r.noFeasibleOption());assertFalse(r.feasibleOptions().isEmpty());assertEquals(12000,r.routeDistanceMetres());}
 @Test void catalogCoordinatesUseCuratedRouteWithoutFabrication(){var service=new RecommendationService(new LocationService(),(a,b)->Optional.of(new RoutingProvider.Route(7200,1500,"","WISEWAY_CURATED_ROUTE")),new FareCalculationService());var r=service.compare(new CompareRequest("Sector 14","Main Campus",28.4595,77.0266,28.4456,77.0420,null,PreferenceProfile.BALANCED,null),Set.of());assertFalse(r.feasibleOptions().isEmpty());}
}
